import pytest

from sales_dashboard.loader import (
    daily_conversion_counts,
    dedupe_sessions,
    parse_session_log,
)
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_as_not_converted():
    events = [{"converted": value} for value in [True, None, False, None]]
    assert conversion_rate(events) == 0.25
    assert conversion_rate([{"converted": None}]) == 0.0


def test_conversion_rate_empty_is_float_zero():
    rate = conversion_rate([])
    assert rate == 0.0
    assert isinstance(rate, float)


def test_pooled_rate_weights_sessions_not_groups():
    groups = {
        "small": [{"converted": True}],
        "large": [{"converted": False}, {"converted": None}, {"converted": True}],
        "empty": [],
    }
    assert pooled_conversion_rate(groups) == 0.5


@pytest.mark.parametrize("groups", [{}, {"empty": []}, {"a": [], "b": []}])
def test_pooled_rate_without_sessions(groups):
    rate = pooled_conversion_rate(groups)
    assert rate == 0.0
    assert isinstance(rate, float)


@pytest.mark.parametrize(
    "counts,days,expected",
    [([1, 2, 4], 0, 0), ([1, 2, 4], 1, 4), ([1, 2, 4], 2, 6),
     ([1, 2, 4], 3, 7), ([1, 2, 4], 10, 7), ([], 0, 0), ([], 3, 0)],
)
def test_conversions_in_window(counts, days, expected):
    assert conversions_in_window(counts, days) == expected


def test_parser_converted_values_and_field_whitespace():
    assert parse_session_log([" a , 1 , 1 \n", " b , -2 , 0 ", " c , 3 , \n"]) == [
        session("a", 1, True), session("b", -2, False), session("c", 3, None)
    ]


def test_parser_skips_blank_whitespace_and_comment_lines():
    lines = ["", " \t\n", "# comment", " \t# ignored,not,a,record", "a,1,1"]
    assert parse_session_log(iter(lines)) == [session("a", 1, True)]
    assert parse_session_log([]) == []


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,0,extra", "a,no,1", "a,1.5,0", "a,,1"])
def test_parser_errors_include_original_line_number(bad_line):
    lines = ["", "  # comment", "good,1,1", " \t", bad_line]
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_session_log(lines)


def test_dedupe_keeps_last_record_not_latest_day():
    events = [
        session("a", 9, True),
        session("b", 2, False),
        session("c", 0, True),
        session("a", 2, None),
        session("b", 2, True),
    ]
    assert dedupe_sessions(events) == [events[2], events[3], events[4]]
    assert dedupe_sessions([]) == []


def test_daily_counts_fills_gaps_and_filters_range():
    events = [
        session("before", 0, True), session("after", 6, True),
        session("a", 1, True), session("b", 1, True),
        session("c", 2, False), session("d", 2, None),
        session("e", 5, True),
    ]
    assert daily_conversion_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_conversion_counts(events, 1, 1) == [2]
    assert daily_conversion_counts(events, 5, 1) == []
    assert daily_conversion_counts([], -1, 1) == [0, 0, 0]


@pytest.mark.parametrize("days,recent", [(0, 0), (1, 0), (2, 1), (3, 1), (4, 2), (20, 2)])
def test_campaign_summary_uses_calendar_days_and_pooled_rate(days, recent):
    groups = {
        "small": [session("a", 1, True)],
        "large": [session("b", 3, True), session("c", 4, False)],
        "empty": [],
    }
    assert campaign_summary(groups, days) == {"rate": 0.667, "recent": recent, "groups": 2}


@pytest.mark.parametrize("groups", [{}, {"empty": []}])
def test_campaign_summary_without_sessions(groups):
    assert campaign_summary(groups, 7) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"converted": True}],
        "empty": [],
        "low": [{"converted": False}],
        "a": [{"converted": True}],
    }
    assert top_converting_groups(groups, 2) == ["a", "z"]
    assert top_converting_groups(groups, 10) == ["a", "z", "low"]
    assert top_converting_groups(groups, 0) == []
    assert top_converting_groups({"empty": []}, 2) == []
    assert top_converting_groups({}, 2) == []


def test_rates_by_group_are_sorted_and_empty_is_none():
    groups = {
        "z": [{"converted": True}, {"converted": None}],
        "b": [],
        "a": [{"converted": False}],
    }
    rates = conversion_rate_by_group(groups)
    assert rates == {"a": 0.0, "b": None, "z": 0.5}
    assert list(rates) == ["a", "b", "z"]
    assert conversion_rate_by_group({}) == {}


@pytest.mark.parametrize(
    "counts,expected",
    [([], 0), ([0, 0], 0), ([-1, -2], 0), ([1, 2, 0, 3], 2),
     ([1, 0, 2, 3, 4], 3), ([1, 2, -1, 3, 4], 2), ([2, 3, 4], 3)],
)
def test_longest_streak_requires_consecutive_positive_counts(counts, expected):
    assert longest_conversion_streak(counts) == expected
